<button data-part="12" id="place" disabled>Place order</button>
<div data-component="tab-bar"></div>
<script>
var inputs=document.querySelectorAll("input[data-price]");
function update(){
  var total=0,count=0;
  inputs.forEach(function(i){
    var q=Math.max(0,parseInt(i.value)||0);
    total+=q*parseFloat(i.dataset.price);
    count+=q;
  });
  document.getElementById("total").textContent=total.toFixed(2);
  document.getElementById("place").disabled=count===0;
}
inputs.forEach(function(i){i.addEventListener("input",update);});
update();
</script>

